library(dplyr)
library(lubridate)
library(ggplot2)
library(phylotools)
library(phangorn)

# Read metadata of sequences accessed from GISAID on 2025/06/11, 
# Search criteria: H5 Influenza A, Avian host, Africa+Asia+Europe, 
# 2020/07/01 - 2022/08/01, Collection date complete, HA complete
bg_sq_md <- readxl::read_xls("data/sq/bg_sq_md.xls")

# align the sequences (full data)
system2("mafft", args = c("--auto", "data/sq/HA.fasta"), stdout = "data/sq/ha_align.fasta")
bg_sq_ha <- read.fasta("data/sq/ha_align.fasta")
bg_sq_ha_ls <- asplit(bg_sq_ha, 1)
bg_sq_ha_m <- sapply(bg_sq_ha_ls, function(x) stringr::str_split(x[2],
                                                                 pattern = "",
                                                                 simplify = FALSE)[[1]])
bg_sq_ha2 <- cbind(bg_sq_ha, t(bg_sq_ha_m))

# Check sequences manually and look for irregular ones
# Remove EPI_ISL_5865695|A/green-winged-teal/Georgia/DT-22246/2020|2020-09-29|HA
bg_sq_ha2 <- bg_sq_ha2[!bg_sq_ha2$seq.name=="EPI_ISL_5865695|A/green-winged-teal/Georgia/DT-22246/2020|2020-09-29|HA",]

# Remove duplicated sequences
bg_sq_ha2 <- bg_sq_ha2[!duplicated(bg_sq_ha2$seq.name),]

# Trim the sequence (start and end) - the position is +2 because the first two columns are seq.name and seq.text
bg_sq_ha2 <- bg_sq_ha2[,-(1771:1840)]
bg_sq_ha2 <- bg_sq_ha2[,-(1096:1098)] # Remove the gaps
bg_sq_ha2 <- bg_sq_ha2[,-(3:63)]
# trimmed_seq_text is new column generated by combining all positions
bg_sq_ha2 <- tidyr::unite(bg_sq_ha2, trimmed_seq_text, !c("seq.name","seq.text"), sep="")

# Remove "," in sequence taxa/names
bg_sq_ha2$seq.name <- gsub(pattern = ",",  
                           replacement = "", 
                           x = bg_sq_ha2$seq.name)
# Write trimmed fasta file
seqinr::write.fasta(sequences = as.list(bg_sq_ha2$trimmed_seq_text), as.string = TRUE,
                    names = bg_sq_ha2$seq.name, file.out = "data/sq/ha_align_trim.fasta")

# Model selection
best_mod <- function(fasta_file){
  seq <- read.phyDat(fasta_file, format = "fasta")
  mt <- modelTest(seq, model = "all", multicore = TRUE, mc.cores = 8)
  return(mt)
}
mt2 <- best_mod("data/sq/ha_align_trim.fasta")
best_mod2 <- mt2[mt2$BIC==min(mt2$BIC), "Model"]
fit2 <- as.pml(mt2, best_mod2)
write.tree(fit2$tree, "data/sq/ha_ml.tree")

# remove sequences that are outliers in temporal signal checked by TempEst
bg_sq_ha2$isolate.id <- sapply(strsplit(bg_sq_ha2$seq.name, "|", fixed = TRUE), function (x) x[1])
bg_sq_ha3 <- bg_sq_ha2 %>% filter(!(isolate.id=="EPI_ISL_4061715"|isolate.id=="EPI_ISL_19010147"|isolate.id=="EPI_ISL_684037"))
seqinr::write.fasta(sequences = as.list(bg_sq_ha3$trimmed_seq_text), as.string = TRUE,
                    names = bg_sq_ha3$seq.name, file.out = "data/sq/ha_align_trim_filter.fasta")

# # Summarise sample size distribution
# Add Year, Month
bg_sq_md$Collection_year <- year(bg_sq_md$Collection_Date)
bg_sq_md$Collection_month <- month(bg_sq_md$Collection_Date)

# Add Continent, Country
bg_sq_md <- bg_sq_md %>%
  tidyr::separate(Location,sep=" / ", c('Continent','Country'))

bg_sq_summary <- bg_sq_md %>%
  group_by(Continent, Collection_year, Collection_month) %>%
  summarise(sample_size = n())
ggplot(data = bg_sq_md, 
