                                                      "EPI_ISL_18006905","EPI_ISL_13370893","EPI_ISL_13369783",
                                                      "EPI_ISL_13370505","EPI_ISL_13369777","EPI_ISL_11922822",
                                                      "EPI_ISL_11922811","EPI_ISL_11922810","EPI_ISL_15023114",
                                                      "EPI_ISL_18458068","EPI_ISL_8440976"))
sq_unsampled21 <- bg_sq_md %>% filter(Isolate_Id %in% c("EPI_ISL_5863567","EPI_ISL_977513","EPI_ISL_5865682",
                                                      "EPI_ISL_779129","EPI_ISL_1114754","EPI_ISL_1665263",
                                                      "EPI_ISL_1191587","EPI_ISL_5863615","EPI_ISL_1114752",
                                                      "EPI_ISL_5863557","EPI_ISL_683751","EPI_ISL_5863497",
                                                      "EPI_ISL_5863358","EPI_ISL_5863089","EPI_ISL_5863491",
                                                      "EPI_ISL_5863749","EPI_ISL_5863641","EPI_ISL_683752",
                                                      "EPI_ISL_5865629","EPI_ISL_5865417","EPI_ISL_1114753",
                                                      "EPI_ISL_5865550","EPI_ISL_5863490","EPI_ISL_5862398"))
sq_unsampled_total <- rbind(sq_unsampled, sq_unsampled22, sq_unsampled21)

# Sampling scheme 1: random 10% of the sample size
bg_sq_uni <- bg_sq_md %>%
  filter(!Isolate_Id %in% sq_unsampled_total$Isolate_Id) %>%
  group_by(Collection_year, Collection_month) %>%
  sample_frac(0.1)
bg_sq_uni <- rbind(bg_sq_uni, sq_unsampled_total)

ggplot(bg_sq_uni, aes(x = ym(paste0(Collection_year,"-",Collection_month)))) +
  geom_bar(stat = "count", aes(fill = Continent)) +
  labs(x = "collection date") +
  theme_bw()
