# Select a subset of sequences
if(!exists("bg_sq_ha3")) {
  bg_sq_ha3 <- read.fasta("data/sq/ha_align_trim_filter.fasta")
}
bg_sq_ha3$isolate.id <- sapply(strsplit(bg_sq_ha3$seq.name, "|", fixed = TRUE), function (x) x[1])
