# clean genome data
clean_genome <- function(read_fasta_file, remove_cols_vector=NULL, irregular_seq_vector=NULL){
  gene <- phylotools::read.fasta(read_fasta_file)
  gene_ls <- asplit(gene, 1)
  gene_m <- sapply(gene_ls, function(x) stringr::str_split(x[2],pattern = "",simplify = FALSE)[[1]])
  gene <- cbind(gene, t(gene_m))
  # Remove duplicated sequences
  gene <- gene[!duplicated(gene$seq.name),]
  # Remove "," in sequence taxa/names
  gene$seq.name <- gsub(pattern = ",", replacement = "", x = gene$seq.name)
  
  if(is.null(remove_cols_vector) & is.null(irregular_seq_vector)){
    # Trim the positions that only have nucleotides in a few sequences
    # Count "-" or non-AGTC in each column
    gene <- gene %>% mutate(across(3:length(gene), factor))
    for(col in colnames(gene)){
      if(! col %in% c("seq.name", "seq.text", "irregular")){
        nt_freq <- plyr::count(gene[,col])
        if("-" %in% nt_freq$x){
          if(nrow(gene)-nt_freq[nt_freq[,1]=="-","freq"] < 0.002*nrow(gene)) {
            gene[gene[,col]!="-","irregular"] <- TRUE
            gene <- gene[, !colnames(gene) == col]
          }    
        }
      }
    }
    # Remove the sequences that have nucleotides only in them
    gene <- gene %>%
      filter(is.na(irregular))
    # trimmed_seq_text is new column generated by combining all positions
    gene <- tidyr::unite(gene, trimmed_seq_text, !c("seq.name","seq.text","irregular"), sep="")
  } else {
    # Remove irregular sequences
    if(!is.null(irregular_seq_vector)) {
      gene <- gene[!gene$seq.name %in% irregular_seq_vector,]
    }
    
    # Trim the sequence (start and end)
    # the position is +2 because the first two columns are seq.name and seq.text
    if(!is.null(remove_cols_vector)) {
      gene <- gene[,-remove_cols_vector]
    }
    # trimmed_seq_text is new column generated by combining all positions
    gene <- tidyr::unite(gene, trimmed_seq_text, !c("seq.name","seq.text"), sep="")
  }
  
  # Remove sequences that have lower than 50% coverage
  gene$coverage <- 1-stringr::str_count(gene$trimmed_seq_text, "-")/nchar(gene$trimmed_seq_text)
  gene <- gene[gene$coverage>0.5,]
  # Write trimmed FASTA file
  fasta_stdout <- paste0(strsplit(read_fasta_file,".fasta",fixed=TRUE)[1],"_trim.fasta")
  seqinr::write.fasta(sequences = as.list(gene$trimmed_seq_text), as.string = TRUE,
                      names = gene$seq.name, file.out = fasta_stdout)
}
clean_genome("data/sq/mp_a.fasta", remove_cols_vector = c(3:43, 1025:1122))
clean_genome("data/sq/np_a.fasta", remove_cols_vector = c(3:944, 2436:2515), irregular_seq_vector = c("EPI_ISL_16839065|A/Cormorant/Namibia/141/2022|2022-01-27|NP"))
clean_genome("data/sq/ns_a.fasta", remove_cols_vector = c(3:99, 940:1027))
clean_genome("data/sq/pa_a.fasta", remove_cols_vector = c(3:138, 2290:2551), irregular_seq_vector = c("EPI_ISL_15433349|A/common_crane_/Yunnan-Huize/22/2021(H5N8)|2021-01-21|PA"))
clean_genome("data/sq/pb2_a.fasta", remove_cols_vector = c(3:32, 241:255, 2066:2068, 2349:2419, 2436:2803), irregular_seq_vector = c("EPI_ISL_15435500|A/common_crane/Yunnan-Huize/24/2021(H5N8)|2021-01-21|PB2"))
clean_genome("data/sq/na_a.fasta")
clean_genome("data/sq/pb1_a.fasta")

